function minimumDeletions(s) {
  let bCount = 0;
  let dp = 0;

  for (let i = 0; i < s.length; i++) {
    if (s[i] === 'b') {
      bCount++;
    } else {
      dp = Math.min(dp + 1, bCount);
    }
  }
  return dp;
}

