function minimumDeletions(s) {
  // Try every cut: everything left of the cut must be 'a', everything right of it 'b'.
  let best = Infinity;
  for (let cut = 0; cut <= s.length; cut++) {
    let removals = 0;
    for (let i = 0; i < cut; i++) if (s[i] === 'b') removals++;
    for (let i = cut; i < s.length; i++) if (s[i] === 'a') removals++;
    best = Math.min(best, removals);
  }
  return best;
}

