function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  const pB = rand();
  let s = '';
  for (let i = 0; i < n; i++) {
    // Drift the chance of 'b' upward along the string so many inputs are nearly balanced.
    const p = Math.min(1, pB * 0.5 + (i / n) * rand());
    s += rand() < p ? 'b' : 'a';
  }
  return [s];
}
